import java.util.*;
public class C_Bear_And_Company_Variant5 {
    static int totalV, totalK, totalS;
    static int[][] freqCount;
    static ArrayList<Integer>[] positionLists;
    static int[][][][] memoCache;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        String inputStr = sc.next();
        char[] chArr = inputStr.toCharArray();
        totalV = totalK = totalS = 0;
        freqCount = new int[n + 1][3];
        positionLists = new ArrayList[3];
        for (int i = 0; i < 3; i++) positionLists[i] = new ArrayList<>();
        int index = 0;
        for (char ch : chArr) {
            System.arraycopy(freqCount[index], 0, freqCount[index + 1], 0, 3);
            index++;
            if (ch == 'V') {
                freqCount[index][0]++;
                totalV++;
                positionLists[0].add(index);
            } else if (ch == 'K') {
                freqCount[index][1]++;
                totalK++;
                positionLists[1].add(index);
            } else {
                freqCount[index][2]++;
                totalS++;
                positionLists[2].add(index);
            }
        }
        memoCache = new int[totalV + 1][totalK + 1][totalS + 1][3];
        for (int[][][] arr3D : memoCache) for (int[][] arr2D : arr3D) for (int[] arr1D : arr2D) Arrays.fill(arr1D, -1);
        System.out.println(minimizeCost(0, 0, 0, 2));
    }

    static int minimizeCost(int v, int k, int s, int last) {
        if (v == totalV && k == totalK && s == totalS) return 0;
        if (memoCache[v][k][s][last] != -1) return memoCache[v][k][s][last];
        int minVal = Integer.MAX_VALUE;
        if (v < totalV) {
            int pIdx = positionLists[0].get(v);
            int costVal = Math.max(freqCount[pIdx][0] - v, 0)
                        + Math.max(freqCount[pIdx][1] - k, 0)
                        + Math.max(freqCount[pIdx][2] - s, 0) - 1;
            minVal = Math.min(minVal, minimizeCost(v + 1, k, s, 0) + costVal);
        }
        if (k < totalK && last != 0) {
            int pIdx = positionLists[1].get(k);
            int costVal = Math.max(freqCount[pIdx][0] - v, 0)
                        + Math.max(freqCount[pIdx][1] - k, 0)
                        + Math.max(freqCount[pIdx][2] - s, 0) - 1;
            minVal = Math.min(minVal, minimizeCost(v, k + 1, s, 1) + costVal);
        }
        if (s < totalS) {
            int pIdx = positionLists[2].get(s);
            int costVal = Math.max(freqCount[pIdx][0] - v, 0)
                        + Math.max(freqCount[pIdx][1] - k, 0)
                        + Math.max(freqCount[pIdx][2] - s, 0) - 1;
            minVal = Math.min(minVal, minimizeCost(v, k, s + 1, 2) + costVal);
        }
        return memoCache[v][k][s][last] = minVal;
    }
}
